:root {
  --ink: #25323b;
  --paper: #fffdf7;
  --line: #d9d5c8;
  --mist: #edf1ef;
  --coral: #c65f47;
  --amber: #e4ad45;
  --slate: #66747a;
}

* {
  box-sizing: border-box;
}

.intake-card {
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 14px;
}

.card-header,
.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 16px;
}

.card-header {
  border-bottom: 1px solid var(--line);
}

.eyebrow,
.accession,
.sample-subtitle,
.specimen-caption,
.custody {
  margin: 0;
}

.eyebrow {
  color: var(--slate);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.1px;
}

.accession {
  margin-top: 3px;
  font-size: 12px;
  font-weight: 600;
}

.status-badge,
.tag {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .7px;
  text-transform: uppercase;
}

.status-badge {
  padding: 5px 8px;
  color: var(--ink);
  background: var(--amber);
  border-radius: 99px;
}

.record-grid {
  display: grid;
  grid-template-columns: 126px 1fr;
  gap: 15px;
  padding: 15px 16px;
}

.specimen {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 139px;
  margin: 0;
  background: var(--mist);
  border: 1px solid var(--line);
  border-radius: 10px 28px 10px 28px;
}

.specimen-mark {
  padding: 12px 8px;
  color: var(--paper);
  background: var(--ink);
  border-radius: 50%;
  font-size: 15px;
  font-weight: 700;
}

.specimen-caption {
  margin-top: 9px;
  color: var(--slate);
  font-size: 11px;
  text-transform: uppercase;
}

.record-content {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.sample-title {
  margin: 0;
  font-size: 21px;
  line-height: 1;
}

.sample-subtitle {
  margin-top: 5px;
  color: var(--slate);
  font-size: 12px;
}

.metadata {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px 16px;
  margin: 11px 0 0;
}

.meta-item dt {
  color: var(--slate);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
}

.meta-item dd {
  margin: 2px 0 0;
  font-size: 12px;
  font-weight: 600;
}

.composition {
  display: flex;
  gap: 6px;
  margin-top: 10px;
}

.tag {
  padding: 4px 6px;
  color: var(--coral);
  background: var(--paper);
  border: 1px solid var(--coral);
  border-radius: 4px;
}

.card-footer {
  min-height: 47px;
  background: var(--mist);
  border-top: 1px solid var(--line);
}

.custody {
  color: var(--slate);
  font-size: 11px;
}

.release-button {
  padding: 7px 11px;
  color: var(--paper);
  background: var(--coral);
  border: 0;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 700;
}
